insert into public.items (id, type, skill_id, difficulty, body, answer, explanation, source_ref, diagnostic, active) values
  ('imp-01', 'fraud', 'impersonation', 1, '{"from":"02-3480-XXXX","avatar":"검","text":"서울중앙지검 수사관입니다. 귀하 명의 대포통장이 발견돼 자산 보호를 위해 안전계좌로 이체가 필요합니다","choices":["사기","정상"]}'::jsonb, 0, '수사기관은 전화로 이체를 요구하지 않아. 20대 이하 보이스피싱 피해자의 85%가 이런 기관사칭형이야.', null, true, true),
  ('imp-02', 'fraud', 'impersonation', 1, '{"from":"[Web발신]","avatar":"금","text":"[금융감독원] 고객님 계좌가 범죄에 연루되어 보호조치가 필요합니다. 아래 앱 설치 후 담당자 안내를 따르세요 http://fss-safe.app","choices":["사기","정상"]}'::jsonb, 0, '금융감독원은 개인에게 문자로 앱 설치나 계좌 보호조치를 안내하지 않아. 원격제어·악성 앱을 깔게 하는 전형적인 수법이야.', null, false, true),
  ('imp-03', 'fraud', 'impersonation', 1, '{"from":"[Web발신]","avatar":"해","text":"고객님 명의로 해외결제 987,000원 승인. 본인이 아닐 경우 고객센터 02-XXX-XXXX로 연락","choices":["사기","정상"]}'::jsonb, 0, '가짜 결제 알림으로 전화를 걸게 만드는 수법이야. 카드사 앱이나 카드 뒷면 번호로 직접 확인해.', null, false, true),
  ('imp-04', 'quiz', 'impersonation', 1, '{"prompt":"검찰 수사관이라며 ''수사 중이니 주변에 알리지 말고 현금을 찾아 직원에게 전달하라''고 한다. 가장 먼저 할 일은?","choices":["전화를 끊고 해당 기관 대표번호로 직접 확인한다","수사에 협조하려고 현금을 준비한다","말한 계좌로 일부만 먼저 보낸다"]}'::jsonb, 0, '수사기관·금융당국은 현금 전달이나 이체를 요구하지 않아. ''비밀로 하라''는 말은 주변의 도움을 막으려는 신호야.', null, false, true),
  ('imp-05', 'quiz', 'impersonation', 1, '{"prompt":"다음 중 진짜 수사기관이나 금융당국이 하지 않는 일은?","choices":["전화로 계좌 이체나 앱 설치를 요구한다","서면으로 출석을 요구한다","대표번호로 걸어온 확인 전화에 답한다"]}'::jsonb, 0, '전화·문자·메신저로 돈, 신분증 사진, 앱 설치를 요구하면 사칭이야. 확인은 내가 대표번호로 직접 걸어서 해.', null, false, true),
  ('loan-01', 'fraud', 'loan_bait', 1, '{"from":"1588-XXXX","avatar":"대","text":"정부지원 저금리 대환대출 대상자입니다. 기존 대출을 먼저 상환하셔야 신청 가능합니다","choices":["사기","정상"]}'::jsonb, 0, '''기존 대출 먼저 갚아라''는 대출빙자형 사기의 전형이야. 정부·금융사는 이런 문자를 보내지 않아.', null, false, true),
  ('loan-02', 'fraud', 'loan_bait', 1, '{"from":"[Web발신]","avatar":"저","text":"신용점수 무관 최대 3천만원 당일 승인! 승인 전 보증보험료 30만원 선입금 필요","choices":["사기","정상"]}'::jsonb, 0, '대출 전에 보증료·수수료·작업비를 먼저 보내라고 하면 사기야. 정상 금융사는 승인 전에 돈을 받지 않아.', null, false, true),
  ('loan-03', 'quiz', 'loan_bait', 1, '{"prompt":"대출 상담원이 ''신용점수를 올려줄 테니 작업비를 보내라''고 한다. 맞는 것은?","choices":["돈을 받고 신용점수를 올려주는 방법은 없다","작업비를 내면 점수가 오른다","일부만 내면 안전하다"]}'::jsonb, 0, '신용점수는 상환 이력 같은 실제 기록으로 매겨져. 돈 받고 점수를 손봐준다는 건 사기야.', null, false, true),
  ('loan-04', 'quiz', 'loan_bait', 1, '{"prompt":"대출 권유 전화가 정상 업체인지 확인하는 방법으로 알맞은 것은?","choices":["금융감독원 ''파인''에서 등록된 금융회사인지 조회한다","문자에 적힌 번호로 전화해 물어본다","상담원이 보내준 앱을 설치한다"]}'::jsonb, 0, '금융감독원 ''파인''(fine.fss.or.kr)에서 제도권 금융회사인지 조회할 수 있어. 문자 속 번호나 링크로 확인하면 같은 사람한테 다시 연결될 뿐이야.', null, false, true),
  ('msg-01', 'fraud', 'messenger', 1, '{"from":"엄마","avatar":"엄","text":"딸 폰 액정 깨져서 임시폰이야. 급하게 상품권 결제해야 하는데 카드번호랑 비밀번호 좀 보내줘","choices":["사기","정상"]}'::jsonb, 0, '가족을 사칭한 메신저 피싱이야. 원래 알던 번호로 전화해 목소리를 확인하기 전엔 절대 보내지 마.', null, true, true),
  ('msg-02', 'fraud', 'messenger', 1, '{"from":"[Web발신]","avatar":"택","text":"고객님 택배가 주소지 불명으로 반송 예정입니다. 주소 확인 http://bit.ly/3xK9","choices":["사기","정상"]}'::jsonb, 0, '모르는 단축 링크로 주소·개인정보를 받는 건 스미싱이야. 택배는 공식 앱에서 직접 확인해.', null, false, true),
  ('msg-03', 'fraud', 'messenger', 1, '{"from":"민지","avatar":"민","text":"저희 결혼합니다 ♥ 모바일 청첩장 확인해 주세요 http://wedding-card.top/mj","choices":["사기","정상"]}'::jsonb, 0, '청첩장·부고를 사칭한 스미싱이 많아. 아는 사람 이름이어도 주소가 이상하면 직접 물어봐.', null, false, true),
  ('msg-04', 'fraud', 'messenger', 1, '{"from":"[Web발신]","avatar":"건","text":"[국민건강보험] 건강검진 결과 통보서가 발송되었습니다. 확인 http://nhis-kr.xyz","choices":["사기","정상"]}'::jsonb, 0, '공공기관을 사칭한 스미싱이야. 주소가 공식 도메인이 아니야.', null, false, true),
  ('msg-05', 'fraud', 'messenger', 1, '{"from":"OO은행","avatar":"은","text":"[OO은행] 11/02 14:21 체크카드 승인 12,500원 (스타벅스). 누적 213,400원","choices":["사기","정상"]}'::jsonb, 1, '링크나 전화 유도 없이 결제 내역만 알려주는 건 일반 알림이야. 이상하면 은행 앱에서 직접 확인해.', null, false, true),
  ('msg-06', 'fraud', 'messenger', 1, '{"from":"OO카드","avatar":"카","text":"[OO카드] 11월 결제 예정 금액은 523,400원입니다. 결제일 11/14","choices":["사기","정상"]}'::jsonb, 1, '링크 없이 결제 예정 금액만 알리는 건 일반 알림이야.', null, false, true),
  ('msg-07', 'fraud', 'messenger', 1, '{"from":"OO은행","avatar":"은","text":"[OO은행] 청년미래적금 가입 심사 결과는 OO은행 앱에서 확인하실 수 있습니다","choices":["사기","정상"]}'::jsonb, 1, '링크 없이 공식 앱으로 확인하라고 안내하는 건 정상 알림이야.', null, false, true),
  ('msg-08', 'quiz', 'messenger', 1, '{"prompt":"친구가 메신저로 급하게 50만원만 보내달라고 한다. 가장 안전한 행동은?","choices":["원래 알던 번호로 전화해 직접 확인한다","메신저로 우리끼리만 아는 걸 물어본다","일단 보내고 나중에 확인한다"]}'::jsonb, 0, '메신저 계정은 해킹되거나 사칭되기 쉬워. 대화 내용만으로는 확인이 안 돼. 직접 통화하기 전에는 송금하지 마.', null, false, true),
  ('inv-01', 'fraud', 'invest_scam', 1, '{"from":"투자 리딩방","avatar":"투","text":"원금 보장 월 30% 수익! 지금 입장하면 VIP방 무료 초대","choices":["사기","정상"]}'::jsonb, 0, '원금 보장에 고수익을 약속하면 불법 유사수신일 가능성이 커. 그런 투자는 없어.', null, false, true),
  ('inv-02', 'quiz', 'invest_scam', 1, '{"prompt":"리딩방에서 받은 앱으로 투자했더니 수익이 크게 났다. 출금하려니 ''세금과 수수료를 먼저 내라''고 한다. 무엇일까?","choices":["가짜 거래 앱일 가능성이 높다","정상적인 출금 절차다","수익이 크니 내도 이득이다"]}'::jsonb, 0, '화면 속 수익은 조작된 숫자일 수 있어. 출금하려면 돈을 더 내라는 건 가짜 거래소의 전형적인 수법이야.', null, false, true),
  ('inv-03', 'quiz', 'invest_scam', 1, '{"prompt":"''원금 보장, 확정 고수익''을 약속하는 투자 권유는?","choices":["불법 유사수신일 가능성이 크다","정부가 인증한 상품이다","먼저 들어갈수록 유리하다"]}'::jsonb, 0, '투자 상품은 원금을 잃을 수 있어. 원금과 고수익을 함께 보장한다면 유사수신을 의심해야 해.', null, false, true),
  ('inv-04', 'quiz', 'invest_scam', 1, '{"prompt":"SNS에서 유명인이 추천하는 투자방 광고를 봤다. 먼저 의심할 것은?","choices":["유명인 사진·영상이 도용됐을 수 있다","유명인이 추천했으니 안전하다","참여자가 많으면 믿을 만하다"]}'::jsonb, 0, '유명인 사진·영상을 도용한 투자 사기 광고가 많아. 투자를 권하는 업체는 ''파인''에서 등록 여부부터 조회해.', null, false, true),
  ('mkt-01', 'fraud', 'market_scam', 1, '{"from":"인스타 DM","avatar":"알","text":"단순 서류·현금 전달 알바, 일당 30만원 당일지급! 경력 무관, 차량 있으면 우대","choices":["사기","정상"]}'::jsonb, 0, '보이스피싱 현금 수거책 모집이야. 몰랐어도 처벌받을 수 있어.', null, false, true),
  ('mkt-02', 'fraud', 'market_scam', 1, '{"from":"중고거래 구매자","avatar":"중","text":"안전결제로 보낼게요! 이 링크에서 결제 확인하고 송금 받으세요 http://safe-pay-trade.shop","choices":["사기","정상"]}'::jsonb, 0, '거래 앱 밖의 링크로 ''안전결제''를 유도하면 가짜 결제 페이지야. 결제는 앱 안의 공식 기능으로만 해.', null, false, true),
  ('mkt-03', 'quiz', 'market_scam', 1, '{"prompt":"중고거래 판매자가 ''앱 채팅 말고 카톡으로 얘기하자''며 선입금을 요구한다. 어떻게 할까?","choices":["거래를 멈춘다. 외부 메신저로 끌어내는 건 사기 신호다","시세보다 싸니 빨리 보낸다","절반만 먼저 보낸다"]}'::jsonb, 0, '플랫폼 밖으로 나가면 신고나 보호를 받기 어려워져. 상대 계좌·연락처는 경찰청 ''사이버캅''에서 사기 이력을 조회할 수 있어.', null, false, true),
  ('mkt-04', 'quiz', 'market_scam', 1, '{"prompt":"알바 공고에서 ''본인 명의 통장을 빌려주면 월 50만원''을 준다고 한다. 통장을 빌려주면?","choices":["처벌받고 금융거래가 제한될 수 있다","돈만 받으면 문제없다","한 달만이면 괜찮다"]}'::jsonb, 0, '통장을 빌려주거나 파는 것 자체가 불법이야. 대포통장으로 쓰이면 처벌과 함께 새 통장 개설 같은 금융거래가 제한될 수 있어.', null, false, true),
  ('scr-01', 'quiz', 'score', 1, '{"prompt":"신용점수를 떨어뜨리는 것은?","choices":["카드값 연체","체크카드 사용"]}'::jsonb, 0, '연체·카드론·현금서비스는 점수를 낮춰. 대출이 있는 20대의 60.7%가 829점 이하 저신용이야.', null, true, true),
  ('scr-02', 'quiz', 'score', 1, '{"prompt":"신용점수 앱에서 내 점수를 자주 조회하면?","choices":["점수에 영향이 없다","조회할 때마다 점수가 내려간다"]}'::jsonb, 0, '본인이 신용점수를 조회하는 건 점수에 영향을 주지 않아. 자주 확인해도 괜찮아.', null, false, true),
  ('scr-03', 'quiz', 'score', 1, '{"prompt":"통신비·건강보험료를 꾸준히 낸 기록은 신용점수에?","choices":["제출하면 가점을 받을 수 있다","아무 상관없다"]}'::jsonb, 0, '통신비·공공요금 같은 비금융 납부 기록을 신용평가사에 제출하면 가점을 받을 수 있어. 금융 이력이 적은 20대에게 특히 유리해.', null, false, true),
  ('scr-04', 'quiz', 'score', 1, '{"prompt":"금융 이력이 거의 없는 사회초년생이 신용을 쌓는 방법은?","choices":["감당할 만큼만 카드를 쓰고 매달 제때 갚는다","카드를 아예 만들지 않는다","한도를 꽉 채워 쓴다"]}'::jsonb, 0, '거래 이력이 없으면 점수를 매길 근거가 부족해. 쓰고 제때 갚는 기록이 쌓이면 좋아져. 한도를 꽉 채워 쓰면 오히려 불리해.', null, false, true),
  ('del-01', 'quiz', 'delinquency', 1, '{"prompt":"카드값을 며칠만 연체해도 괜찮을까?","choices":["짧은 연체도 기록이 남고 점수에 영향을 줄 수 있다","3개월 전까지는 아무 영향이 없다"]}'::jsonb, 0, '금액과 기간에 따라 짧은 연체도 신용평가사에 공유될 수 있어. 결제일을 놓쳤으면 바로 갚는 게 피해를 줄여.', null, false, true),
  ('del-02', 'quiz', 'delinquency', 1, '{"prompt":"연체가 여러 건이면 무엇부터 갚는 게 신용에 유리할까?","choices":["가장 오래된 연체부터","가장 최근 연체부터"]}'::jsonb, 0, '연체 기간이 길수록 신용점수에 더 크게 반영돼. 보통 오래된 연체부터 갚는 게 좋아.', null, false, true),
  ('del-03', 'case', 'delinquency', 1, '{"scenario":"학자금 대출 상환이 어려워졌다.","prompt":"가장 먼저 할 일은?","choices":["한국장학재단에 상환 유예 같은 제도를 문의한다","연락을 피하고 기다린다","카드론으로 막는다"]}'::jsonb, 0, '20대 대출의 39%가 학자금 대출이야. 상환 유예 같은 제도가 있으니 연체가 쌓이기 전에 먼저 문의하는 게 핵심이야.', null, false, true),
  ('del-04', 'quiz', 'delinquency', 1, '{"prompt":"결제일을 놓치지 않는 방법으로 가장 좋은 것은?","choices":["결제 계좌에 자동이체를 걸고 잔액 알림을 켠다","결제일을 머릿속으로 기억한다"]}'::jsonb, 0, '깜빡해서 생기는 연체가 의외로 많아. 자동이체에 잔액 부족 알림까지 켜두면 대부분 막을 수 있어.', null, false, true),
  ('rev-01', 'quiz', 'revolving', 1, '{"prompt":"리볼빙을 계속 쓰면?","choices":["수수료가 쌓여 빚이 불어난다","이자 없이 미룰 수 있다"]}'::jsonb, 0, '넘긴 금액에 연 15~19% 수준의 수수료가 붙어 원금이 잘 안 줄어.', null, false, true),
  ('rev-02', 'quiz', 'revolving', 1, '{"prompt":"카드 결제 화면의 ''최소결제''나 ''일부결제금액이월약정''은 무엇일까?","choices":["리볼빙","무이자 할부"]}'::jsonb, 0, '이름은 달라도 결제액 일부만 내고 나머지를 넘기는 리볼빙이야. 모르고 가입된 경우도 많으니 카드 앱에서 확인해.', null, false, true),
  ('rev-03', 'case', 'revolving', 1, '{"scenario":"이번 달 카드값 100만원 중 10%만 결제하고 나머지는 리볼빙했다.","prompt":"다음 달에는?","choices":["넘긴 90만원에 수수료가 붙어 다음 달 청구에 더해진다","90만원은 다음 달에 수수료 없이 나간다"]}'::jsonb, 0, '넘긴 금액에 높은 수수료가 붙어 다음 달 카드값에 얹혀. 계속 넘기면 매달 수수료만 내고 원금은 거의 안 줄어.', null, false, true),
  ('rev-04', 'quiz', 'revolving', 1, '{"prompt":"리볼빙에서 빠져나오는 방법으로 알맞은 것은?","choices":["새 사용을 줄이고 이월 잔액부터 갚은 뒤 약정을 해지한다","결제 비율을 더 낮춘다"]}'::jsonb, 0, '결제 비율을 낮추면 당장은 편해도 수수료가 더 커져. 이월된 잔액을 먼저 줄이는 게 출구야.', null, false, true),
  ('cash-01', 'quiz', 'cash_advance', 1, '{"prompt":"현금서비스(단기카드대출)를 받으면?","choices":["높은 이자가 붙고 신용점수에 불리할 수 있다","카드 혜택이라 부담이 없다"]}'::jsonb, 0, '현금서비스는 금리가 높은 대출이야. 자주 쓰면 자금 사정이 빠듯하다는 신호로 보여 점수에 불리할 수 있어.', null, false, true),
  ('cash-02', 'quiz', 'cash_advance', 1, '{"prompt":"카드론은 무엇일까?","choices":["카드사에서 받는 대출","카드 포인트 적립 서비스"]}'::jsonb, 0, '카드론은 장기카드대출, 즉 카드사 대출이야. 앱에서 몇 번 누르면 나오지만 금리가 높고 대출 기록으로 남아.', null, false, true),
  ('cash-03', 'case', 'cash_advance', 1, '{"scenario":"월세 낼 돈이 3일 모자란다.","prompt":"가장 나은 선택은?","choices":["집주인에게 미리 사정을 말하고 날짜를 조정한다","현금서비스로 막고 다음 달 갚는다","카드론을 넉넉히 받아둔다"]}'::jsonb, 0, '며칠짜리 문제라면 고금리 대출보다 일정 조정이 손해가 적어. 급할 때마다 카드 대출로 막는 습관이 다중채무의 시작이 되기 쉬워.', null, false, true),
  ('lns-01', 'quiz', 'loan_structure', 1, '{"prompt":"연 5% 복리로 10년 두면 원금의 약 몇 배?","choices":["약 1.6배","약 1.5배"]}'::jsonb, 0, '1.05를 10번 곱하면 약 1.63. 이자에 이자가 붙어서 단리(1.5배)보다 커져. 빚도 똑같이 불어나.', null, false, true),
  ('lns-02', 'quiz', 'loan_structure', 1, '{"prompt":"빌린 돈으로 산 주식이 급락하면 생길 수 있는 일은?","choices":["강제로 팔린다(반대매매)","아무 일도 없다"]}'::jsonb, 0, '담보 가치가 떨어지면 증권사가 강제로 팔아. 손실이 확정되고 빚은 남아. 20대 신용융자 잔고는 1년 새 2배 넘게 늘었어.', null, false, true),
  ('lns-03', 'quiz', 'loan_structure', 1, '{"prompt":"여러 곳에서 빌린 다중채무가 위험한 이유는?","choices":["갚는 날과 이자가 겹쳐 연체로 이어지기 쉽다","대출이 많을수록 신용점수가 오른다"]}'::jsonb, 0, '대출이 여러 개면 상환일이 흩어지고 이자 부담이 커져. 한 곳이 밀리면 줄줄이 연체되기 쉬워.', null, false, true),
  ('lns-04', 'quiz', 'loan_structure', 1, '{"prompt":"같은 금액을 빌릴 때 보통 금리가 가장 높은 곳은?","choices":["대부업체","은행"]}'::jsonb, 0, '보통 은행 < 저축은행 < 카드·캐피탈 < 대부업 순으로 금리가 높아져. 은행이 어려우면 정책서민금융부터 알아봐.', null, false, true),
  ('reg-01', 'quiz', 'registry', 1, '{"prompt":"전세 계약 전에 등기부등본에서 꼭 확인할 것은?","choices":["집주인이 누구인지와 근저당 같은 빚","집의 인테리어 상태"]}'::jsonb, 0, '등기부에서 실제 소유자와 근저당(집을 담보로 한 빚)을 확인해. 빚이 많으면 보증금을 못 돌려받을 위험이 커져.', null, true, true),
  ('reg-02', 'fraud', 'registry', 1, '{"from":"공인중개사","avatar":"중","text":"집주인분이 해외 출장 중이라 계약금은 동생분 계좌로 보내주시면 됩니다","choices":["사기","정상"]}'::jsonb, 0, '보증금·계약금은 등기부상 소유자 본인 계좌로만 보내야 해. 전세사기 피해자의 75%가 20~30대야.', null, false, true),
  ('reg-03', 'quiz', 'registry', 1, '{"prompt":"등기부등본에서 근저당 같은 빚이 적혀 있는 곳은?","choices":["을구","갑구"]}'::jsonb, 0, '갑구에는 소유권, 을구에는 근저당·전세권 같은 소유권 외의 권리가 적혀 있어.', null, false, true),
  ('reg-04', 'case', 'registry', 1, '{"scenario":"집주인 대신 대리인이 나와서 계약하자고 한다.","prompt":"무엇을 확인해야 할까?","choices":["집주인의 위임장·인감증명서를 보고 집주인과 직접 통화한다","대리인의 명함","중개사가 괜찮다고 한 말"]}'::jsonb, 0, '대리 계약이면 위임장과 인감증명서를 확인하고 집주인과 직접 통화해. 돈은 등기부상 소유자 계좌로 보내.', null, false, true),
  ('reg-05', 'quiz', 'registry', 1, '{"prompt":"매매가 2억원짜리 빌라에 전세 1억 9천만원. 이 집은?","choices":["깡통전세 위험이 크다","전세가가 높으니 좋은 집이다"]}'::jsonb, 0, '전세가가 매매가에 가까우면 집값이 조금만 떨어져도 보증금을 다 돌려받지 못할 수 있어.', null, false, true),
  ('mov-01', 'quiz', 'move_in', 1, '{"prompt":"이사하고 전입신고를 하면 대항력은 언제 생길까?","choices":["다음 날 0시","신고 즉시"]}'::jsonb, 0, '대항력은 이사와 전입신고를 마친 다음 날 0시부터 생겨. 그 사이 집주인이 받은 대출이 내 보증금보다 앞설 수 있어.', null, false, true),
  ('mov-02', 'quiz', 'move_in', 1, '{"prompt":"전입신고와 확정일자를 함께 갖추면 생기는 것은?","choices":["집이 경매로 넘어가도 순위에 따라 보증금을 먼저 받을 권리","월세를 깎을 권리"]}'::jsonb, 0, '전입신고(대항력)에 확정일자까지 받으면 우선변제권이 생겨. 경매 때 순위에 따라 보증금을 돌려받을 수 있어.', null, false, true),
  ('mov-03', 'case', 'move_in', 1, '{"scenario":"전세 계약 기간 중에 주민등록만 잠깐 다른 곳으로 옮기려 한다.","prompt":"문제는?","choices":["대항력을 잃어 보증금 보호가 약해질 수 있다","아무 문제 없다"]}'::jsonb, 0, '대항력은 전입을 유지해야 이어져. 계약 중에 주소를 옮기면 보호를 잃을 수 있어.', null, false, true),
  ('mov-04', 'quiz', 'move_in', 1, '{"prompt":"확정일자는 어디서 받을까?","choices":["주민센터나 온라인(인터넷등기소 등)","집주인에게"]}'::jsonb, 0, '주민센터에서 받거나 인터넷등기소에서 온라인으로 신청할 수 있어. 이사 당일 전입신고와 같이 처리해.', null, false, true),
  ('grt-01', 'quiz', 'guarantee', 1, '{"prompt":"전세보증금반환보증에 가입하면?","choices":["집주인이 보증금을 못 돌려줘도 보증기관이 대신 돌려준다","월세를 대신 내준다"]}'::jsonb, 0, 'HUG·HF·SGI 같은 보증기관이 먼저 돌려주고 집주인에게 받아내는 구조야.', null, false, true),
  ('grt-02', 'quiz', 'guarantee', 1, '{"prompt":"전세보증금반환보증은 언제 확인하는 게 가장 좋을까?","choices":["계약 전에 가입 가능한 집인지","보증금을 못 받게 된 뒤"]}'::jsonb, 0, '빚이 많거나 전세가가 너무 높은 집은 가입이 거절될 수 있어. 계약 전에 확인하면 위험한 집을 미리 거를 수 있어.', null, false, true),
  ('grt-03', 'quiz', 'guarantee', 1, '{"prompt":"전세보증금반환보증을 취급하는 곳이 아닌 것은?","choices":["대부업체","주택도시보증공사(HUG)","한국주택금융공사(HF)"]}'::jsonb, 0, '전세보증은 HUG, HF, SGI서울보증에서 취급해. 그 밖의 곳에서 보증을 해준다고 하면 의심해.', null, false, true),
  ('grt-04', 'case', 'guarantee', 1, '{"scenario":"집주인이 ''보증보험 가입할 거면 계약 안 한다''고 한다.","prompt":"어떻게 받아들여야 할까?","choices":["가입이 어려운 집일 수 있으니 계약을 다시 따져본다","집주인 기분을 맞춰 가입을 포기한다"]}'::jsonb, 0, '보증 가입을 막는 건 집에 문제가 있다는 신호일 수 있어. 보증금은 내 전 재산일 수 있으니 그냥 넘기지 마.', null, false, true),
  ('cls-01', 'quiz', 'closing', 1, '{"prompt":"잔금 치르는 날 다시 확인할 것은?","choices":["등기부를 다시 떼서 새 빚이 생겼는지","집 열쇠 개수"]}'::jsonb, 0, '계약일과 잔금일 사이에 근저당이 새로 잡힐 수 있어. 잔금 직전에 등기부를 다시 확인해.', null, false, true),
  ('cls-02', 'quiz', 'closing', 1, '{"prompt":"잔금일에 할 일의 순서로 알맞은 것은?","choices":["등기부 재확인 → 소유자 계좌로 잔금 → 전입신고·확정일자","잔금 송금 → 한 달 뒤 전입신고"]}'::jsonb, 0, '확인하고, 소유자에게 보내고, 그날 바로 전입신고와 확정일자까지. 하루라도 미루면 보호가 늦어져.', null, false, true),
  ('cls-03', 'quiz', 'closing', 1, '{"prompt":"전세 계약서에 넣으면 좋은 특약은?","choices":["잔금일 다음 날까지 집주인은 새 담보대출을 받지 않는다","보증금은 집주인이 원할 때 돌려준다"]}'::jsonb, 0, '대항력이 다음 날 0시에 생기는 틈을 노린 대출을 막는 특약이야. 어기면 계약 해제·손해배상이 가능하다는 내용도 같이 넣어.', null, false, true),
  ('cls-04', 'quiz', 'closing', 1, '{"prompt":"계약금은 누구 계좌로 보내야 할까?","choices":["등기부상 소유자 본인 계좌","중개사 개인 계좌"]}'::jsonb, 0, '돈은 언제나 등기부에 적힌 소유자 본인에게. 다른 사람 계좌를 요구하면 멈추고 확인해.', null, false, true),
  ('emg-01', 'quiz', 'emergency', 1, '{"prompt":"비상금은 보통 얼마 정도를 목표로 할까?","choices":["생활비 3~6개월분","월급 1주일분"]}'::jsonb, 0, '갑자기 일이 끊기거나 큰 지출이 생겨도 버틸 수 있는 기간이야. 한 번에 못 모으면 1개월분부터 시작해.', null, true, true),
  ('emg-02', 'quiz', 'emergency', 1, '{"prompt":"비상금을 넣어두기 좋은 곳은?","choices":["언제든 꺼낼 수 있는 파킹통장·수시입출금 통장","주식·코인 계좌"]}'::jsonb, 0, '비상금은 급할 때 바로 꺼낼 수 있고 가격이 흔들리지 않아야 해.', null, false, true),
  ('emg-03', 'case', 'emergency', 1, '{"scenario":"비상금 없이 적금만 넣다가 갑자기 병원비 50만원이 생겼다.","prompt":"흔히 벌어지는 일은?","choices":["적금을 깨거나 카드 대출을 쓰게 된다","아무 일도 없다"]}'::jsonb, 0, '청년도약계좌 중도해지율이 1년 반 만에 2배(15.9%)가 된 것도 이 구조야. 적금보다 비상금을 먼저 만들어야 해지를 막을 수 있어.', null, false, true),
  ('fix-01', 'quiz', 'fixed_cost', 1, '{"prompt":"다음 중 고정비는?","choices":["월세·통신비·구독료","친구와 저녁 약속"]}'::jsonb, 0, '고정비는 매달 비슷하게 자동으로 나가는 돈이야. 가계부를 쓸 때 가장 먼저 정리할 부분이야.', null, false, true),
  ('fix-02', 'quiz', 'fixed_cost', 1, '{"prompt":"돈이 새는 걸 막을 때 줄이면 효과가 가장 오래가는 것은?","choices":["매달 나가는 구독·통신비","오늘 커피 한 잔"]}'::jsonb, 0, '고정비는 한 번 줄이면 매달 효과가 이어져. 안 쓰는 구독부터 정리해.', null, false, true),
