-- 자동 생성: scripts/build-content.mjs (직접 수정하지 말 것)
-- 스킬 19개, 문제 78개

on conflict (id) do update set stat = excluded.stat, name = excluded.name, sort = excluded.sort;

on conflict (id) do update set
  type = excluded.type, skill_id = excluded.skill_id, difficulty = excluded.difficulty, body = excluded.body,
  answer = excluded.answer, explanation = excluded.explanation, source_ref = excluded.source_ref,
  diagnostic = excluded.diagnostic, active = excluded.active;

-- 파일에서 빠진 문제는 비활성화 (풀이 기록이 참조하므로 지우지 않는다)
update public.items set active = false
where id not in ('imp-01', 'imp-02', 'imp-03', 'imp-04', 'imp-05', 'loan-01', 'loan-02', 'loan-03', 'loan-04', 'msg-01', 'msg-02', 'msg-03', 'msg-04', 'msg-05', 'msg-06', 'msg-07', 'msg-08', 'inv-01', 'inv-02', 'inv-03', 'inv-04', 'mkt-01', 'mkt-02', 'mkt-03', 'mkt-04', 'scr-01', 'scr-02', 'scr-03', 'scr-04', 'del-01', 'del-02', 'del-03', 'del-04', 'rev-01', 'rev-02', 'rev-03', 'rev-04', 'cash-01', 'cash-02', 'cash-03', 'lns-01', 'lns-02', 'lns-03', 'lns-04', 'reg-01', 'reg-02', 'reg-03', 'reg-04', 'reg-05', 'mov-01', 'mov-02', 'mov-03', 'mov-04', 'grt-01', 'grt-02', 'grt-03', 'grt-04', 'cls-01', 'cls-02', 'cls-03', 'cls-04', 'emg-01', 'emg-02', 'emg-03', 'fix-01', 'fix-02', 'fix-03', 'fix-04', 'sav-01', 'sav-02', 'sav-03', 'auto-01', 'auto-02', 'auto-03', 'pol-01', 'pol-02', 'pol-03', 'pol-04');
